        }
      }
    }

    this.root.position.copy(this.position);
  }

  takeDamage(amount) {
    this.health -= amount;
    if (this.health <= 0) {
      this.state = 'down';
      this.root.rotation.x = Math.PI / 2;
      this.root.position.y = this.collisions.getGroundHeight(this.position.x, this.position.z) + 0.15;
    }
  }
